/**
 * Koko icons: generated by `npm run icons` from public/brand/koko-mark.svg.
 * Fails if an icon is missing, has the wrong size, or if a default Next.js /
 * create-next-app asset comes back.
 */
import { createHash } from "node:crypto";
import { existsSync, readFileSync, readdirSync, statSync } from "node:fs";
import path from "node:path";
import sharp from "sharp";
import { describe, expect, it } from "vitest";

const APP_DIR = path.resolve(__dirname, "..", "..");
const file = (...parts: string[]) => path.join(APP_DIR, ...parts);

/** SHA-256 of the files replaced on 2026-11-05: they must never come back. */
const FORBIDDEN_HASHES = new Map([
  // Default create-next-app favicon.ico (Next.js logo)
  ["c28fdd2a4f31e2dc64f653962286da5c82a4cdfc518b242d32812c624e9a19a4", "favicon Next.js par défaut"],
  // 1x1 placeholder that used to be public/icons/icon-192.png and icon-512.png
  ["c414cd0e204de974f73753c7e28d7638e7b3691bb8b1a2bab6b25bb7fed7ce77", "icône vide 1x1"],
]);
const TEMPLATE_FILES = ["next.svg", "vercel.svg", "globe.svg", "file.svg", "window.svg"];

interface ManifestIcon {
  src: string;
  sizes: string;
  type: string;
  purpose?: string;
}
const manifest = JSON.parse(readFileSync(file("public", "manifest.json"), "utf8")) as {
  name: string;
  short_name: string;
  lang: string;
  display: string;
  start_url: string;
  theme_color: string;
  background_color: string;
  icons: ManifestIcon[];
};

function walk(dir: string, out: string[] = []): string[] {
  for (const entry of readdirSync(dir)) {
    const full = path.join(dir, entry);
    if (statSync(full).isDirectory()) walk(full, out);
    else out.push(full);
  }
  return out;
}

describe("PWA manifest", () => {
  it("describes Koko with the brand colours", () => {
    expect(manifest.name).toBe("Koko");
    expect(manifest.short_name).toBe("Koko");
    expect(manifest.lang).toBe("fr");
    expect(manifest.display).toBe("standalone");
    expect(manifest.start_url).toBe("/tableau-de-bord");
    expect(manifest.theme_color).toMatch(/^#[0-9a-f]{6}$/i);
    expect(manifest.background_color).toMatch(/^#[0-9a-f]{6}$/i);
  });

  it("lists icons that exist, with their real size", async () => {
    for (const icon of manifest.icons) {
      const onDisk = file("public", ...icon.src.split("/").filter(Boolean));
      expect(existsSync(onDisk), icon.src).toBe(true);
      const meta = await sharp(onDisk).metadata();
      expect(`${meta.width}x${meta.height}`, icon.src).toBe(icon.sizes);
      expect(icon.type).toBe("image/png");
    }
  });

  it("has 192 and 512 icons for 'any' and for 'maskable'", () => {
    const has = (size: string, purpose: string) =>
      manifest.icons.some((icon) => icon.sizes === size && (icon.purpose ?? "any").split(" ").includes(purpose));
    for (const size of ["192x192", "512x512"]) {
      expect(has(size, "any"), `${size} any`).toBe(true);
      expect(has(size, "maskable"), `${size} maskable`).toBe(true);
    }
  });

  it("maskable icons are opaque edge to edge (Android crops them)", async () => {
    for (const icon of manifest.icons.filter((i) => i.purpose === "maskable")) {
      const stats = await sharp(file("public", ...icon.src.split("/").filter(Boolean))).stats();
      expect(stats.isOpaque, icon.src).toBe(true);
    }
  });
});

describe("App Router icon files", () => {
  it.each([
    ["src/app/icon.png", 512, 512],
    ["src/app/apple-icon.png", 180, 180],
    ["src/app/opengraph-image.png", 1200, 630],
    ["src/app/twitter-image.png", 1200, 630],
  ])("%s is %ix%i", async (relative, width, height) => {
    const meta = await sharp(file(...relative.split("/"))).metadata();
    expect([meta.width, meta.height]).toEqual([width, height]);
  });

  it("apple-icon and link previews have no transparency (iOS shows it as black)", async () => {
    for (const relative of ["src/app/apple-icon.png", "src/app/opengraph-image.png", "src/app/twitter-image.png"]) {
      expect((await sharp(file(...relative.split("/"))).stats()).isOpaque, relative).toBe(true);
    }
  });

  it("favicon.ico holds 16, 32 and 48 px images", () => {
    const ico = readFileSync(file("src", "app", "favicon.ico"));
    expect(ico.readUInt16LE(2)).toBe(1); // ICO
    const sizes = Array.from({ length: ico.readUInt16LE(4) }, (_, i) => ico.readUInt8(6 + 16 * i));
    expect(sizes).toEqual([16, 32, 48]);
  });

  it("icon.svg is the Koko mark", () => {
    const svg = readFileSync(file("src", "app", "icon.svg"), "utf8");
    expect(svg).toContain("#9e3b5a");
    expect(svg).toContain("#d98e73");
    expect(svg).not.toMatch(/NaN|Infinity/);
  });
});

describe("no default Next.js / create-next-app asset", () => {
  const files = [...walk(file("public")), ...walk(file("src", "app"))];

  it("none of the template SVGs exist", () => {
    const names = files.map((f) => path.basename(f));
    for (const template of TEMPLATE_FILES) expect(names, template).not.toContain(template);
  });

  it("the old default favicon and the empty placeholder are gone", () => {
    for (const f of files.filter((f) => /\.(ico|png|svg)$/.test(f))) {
      const hash = createHash("sha256").update(readFileSync(f)).digest("hex");
      expect(FORBIDDEN_HASHES.get(hash), path.relative(APP_DIR, f)).toBeUndefined();
    }
  });
});

describe("one source for the mark", () => {
  it("the master SVG has the same shape and colours as the header logo", () => {
    const master = readFileSync(file("public", "brand", "koko-mark.svg"), "utf8");
    const header = readFileSync(file("src", "components", "layout", "Brand.tsx"), "utf8");
    const d = (source: string) => source.match(/<path[\s\S]*?\bd="([^"]+)"/)?.[1];
    expect(d(master)).toBeTruthy();
    expect(d(master)).toBe(d(header));
    expect(master).toContain('cx="62" cy="72" r="6"');
    expect(header).toContain('cx="62" cy="72" r="6"');
    expect(header).toContain('fill="#d98e73"');
    expect(master).toContain('fill="#d98e73"');
  });
});
